import java.util.*;

class AllOne {
  // doubly linked list of count buckets in increasing count order, each holding its keys
  private static class Bucket {
    int count;
    Set<String> keys = new LinkedHashSet<>();
    Bucket prev, next;

    Bucket(int count) {
      this.count = count;
    }
  }

  private final Bucket head = new Bucket(0), tail = new Bucket(0);
  private final Map<String, Bucket> where = new HashMap<>();

  public AllOne() {
    head.next = tail;
    tail.prev = head;
  }

  public void inc(String key) {
    Bucket cur = where.getOrDefault(key, head);
    Bucket next = cur.next;
    if (next == tail || next.count != cur.count + 1) next = insertAfter(cur, cur.count + 1);
    next.keys.add(key);
    where.put(key, next);
    if (cur != head) removeKey(cur, key);
  }

  public void dec(String key) {
    Bucket cur = where.get(key);
    if (cur == null) return;
    if (cur.count == 1) where.remove(key);
    else {
      Bucket prev = cur.prev;
      if (prev == head || prev.count != cur.count - 1) prev = insertAfter(cur.prev, cur.count - 1);
      prev.keys.add(key);
      where.put(key, prev);
    }
    removeKey(cur, key);
  }

  public String getMaxKey() {
    return tail.prev == head ? "" : tail.prev.keys.iterator().next();
  }

  public String getMinKey() {
    return head.next == tail ? "" : head.next.keys.iterator().next();
  }

  private Bucket insertAfter(Bucket b, int count) {
    Bucket nb = new Bucket(count);
    nb.prev = b;
    nb.next = b.next;
    b.next.prev = nb;
    b.next = nb;
    return nb;
  }

  private void removeKey(Bucket b, String key) {
    b.keys.remove(key);
    if (b.keys.isEmpty()) {
      b.prev.next = b.next;
      b.next.prev = b.prev;
    }
  }
}
